const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: 'State of Developer Ecosystem 2024: Language Trends, Satisfaction, and Strategic Shifts' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative shapes
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.5, h: 5.625, fill: { color: theme.primary } });
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 0, w: 0.1, h: 5.625, fill: { color: theme.accent } });

  slide.addText("STATE OF DEVELOPER ECOSYSTEM 2024", {
    x: 1, y: 1.5, w: 8, h: 0.5,
    fontSize: 18, fontFace: "Arial",
    color: theme.accent, bold: true, charSpacing: 4
  });

  slide.addText("Language Trends,\nSatisfaction, and\nStrategic Shifts", {
    x: 1, y: 2.2, w: 8.5, h: 1.8,
    fontSize: 54, fontFace: "Arial",
    color: theme.primary, bold: true,
    breakLine: true, margin: 0
  });

  slide.addText("Key insights from JetBrains' survey of 23,262 developers worldwide.", {
    x: 1, y: 4.2, w: 8, h: 0.6,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary, margin: 0
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 2, title: 'Python Closes the Gap: 8 Years of Language Usage Shifts' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  // Top 8 languages
  const chartData = [
    { name: "JavaScript", labels: ["2017", "2020", "2022", "2024"], values: [65, 70, 65, 61] },
    { name: "Python", labels: ["2017", "2020", "2022", "2024"], values: [32, 55, 53, 57] },
    { name: "HTML/CSS", labels: ["2017", "2020", "2022", "2024"], values: [60, 61, 54, 51] },
    { name: "Java", labels: ["2017", "2020", "2022", "2024"], values: [47, 54, 48, 46] },
    { name: "TypeScript", labels: ["2017", "2020", "2022", "2024"], values: [12, 28, 34, 37] },
    { name: "Go", labels: ["2017", "2020", "2022", "2024"], values: [8, 19, 19, 18] },
    { name: "Rust", labels: ["2017", "2020", "2022", "2024"], values: [0, 7, 9, 11] },
    { name: "PHP", labels: ["2017", "2020", "2022", "2024"], values: [30, 27, 20, 17] }
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.5, y: 1.2, w: 6.5, h: 3.8,
    chartColors: ["F59E0B", "3B82F6", "EF4444", "10B981", "6366F1", "EC4899", "8B5CF6", "14B8A6"],
    lineSize: 3, lineSmooth: true,
    showLegend: true, legendPos: "r",
    valAxisMinVal: 0, valAxisMaxVal: 80,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    catAxisLabelColor: "64748B", valAxisLabelColor: "64748B",
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true }
  });

  slide.addText([
    { text: "Key Shifts\n", options: { bold: true, fontSize: 16, color: theme.primary, breakLine: true } },
    { text: "JavaScript", options: { bold: true, color: theme.primary } },
    { text: " peaked at 70% in 2020 before declining to 61%.\n\n", options: { breakLine: true } },
    { text: "Python", options: { bold: true, color: theme.primary } },
    { text: " rose from 32% to 57%, nearly closing the gap with JS.\n\n", options: { breakLine: true } },
    { text: "TypeScript", options: { bold: true, color: theme.primary } },
    { text: " tripled its share from 12% to 37%.\n\n", options: { breakLine: true } },
    { text: "PHP", options: { bold: true, color: theme.primary } },
    { text: " saw a significant drop from 30% to 17%.", options: { breakLine: true } }
  ], {
    x: 7.2, y: 1.2, w: 2.5, h: 3.5,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, valign: "top"
  });

  // Badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 9.1, y: 5.15, w: 0.6, h: 0.35, fill: { color: theme.primary }, rectRadius: 0.15 });
  slide.addText("02", { x: 9.1, y: 5.15, w: 0.6, h: 0.35, fontSize: 11, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 3, title: 'Python Is Now the #1 Primary Language at 35%' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.4, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true
  });

  const chartData = [
    {
      name: "Primary Language",
      labels: ["Python", "Java", "JavaScript", "TypeScript", "SQL"].reverse(),
      values: [35, 30, 28, 19, 17].reverse()
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.2, w: 6.5, h: 3.8,
    barDir: "bar",  // Horizontal bar
    chartColors: [theme.primary],
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: "1E293B",
    showLegend: false,
    valAxisMinVal: 0, valAxisMaxVal: 40,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    catAxisLabelColor: "1E293B", valAxisLabelColor: "64748B",
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true }
  });

  slide.addText([
    { text: "Ecosystem Lock-in\n", options: { bold: true, fontSize: 16, color: theme.primary, breakLine: true } },
    { text: "Developers show strong loyalty to their chosen ecosystems.\n\n", options: { breakLine: true } },
    { text: "Adoption Intent is Modest:\n", options: { bold: true, color: theme.primary, breakLine: true } },
    { text: "• Python: 6%\n", options: { breakLine: true } },
    { text: "• TypeScript: 5%\n", options: { breakLine: true } },
    { text: "• Java: 4%\n", options: { breakLine: true } },
    { text: "• SQL: 4%\n\n", options: { breakLine: true } },
    { text: "All adoption intent sits below 6%, highlighting the 'comfort zone effect' where developers rarely switch their primary stack.", options: { breakLine: true } }
  ], {
    x: 7.2, y: 1.2, w: 2.5, h: 3.5,
    fontSize: 14, fontFace: "Arial",
    color: theme.secondary, valign: "top"
