  slide.background = { color: theme.bg };

  // Decorative shapes
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.5, h: 5.625, fill: { color: theme.primary } });
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 0, w: 0.1, h: 5.625, fill: { color: theme.accent } });

  slide.addText("STATE OF DEVELOPER ECOSYSTEM 2024", {
    x: 1, y: 1.5, w: 8, h: 0.5,
    fontSize: 18, fontFace: "Arial",
    color: theme.accent, bold: true, charSpacing: 4
  });

  slide.addText("Language Trends,\\nSatisfaction, and\\nStrategic Shifts", {
    x: 1, y: 2.2, w: 8.5, h: 1.8,
    fontSize: 54, fontFace: "Arial",
    color: theme.primary, bold: true,
